  static const double full = 999;

  /// Cards and tiles.
  static const BorderRadius card = BorderRadius.all(Radius.circular(md));

  /// Buttons and inputs.
  static const BorderRadius button = BorderRadius.all(Radius.circular(sm));

  /// Deal badges (nearly square: they are stamps, not pills).
  static const BorderRadius badge = BorderRadius.all(Radius.circular(xs));

  /// Bottom sheets.
  static const BorderRadius sheet = BorderRadius.vertical(
    top: Radius.circular(xl),
  );
}

/// 4-pt spacing scale in dp.
abstract final class BrandSpacing {
  /// Step 0: 0 dp.
  static const double s0 = 0;

  /// Step 1: 2 dp.
  static const double s1 = 2;

  /// Step 2: 4 dp.
  static const double s2 = 4;

  /// Step 3: 8 dp.
  static const double s3 = 8;

  /// Step 4: 12 dp.
  static const double s4 = 12;

  /// Step 5: 16 dp.
  static const double s5 = 16;

  /// Step 6: 20 dp.
  static const double s6 = 20;

  /// Step 7: 24 dp.
  static const double s7 = 24;

  /// Step 8: 32 dp.
  static const double s8 = 32;

  /// Step 9: 40 dp.
  static const double s9 = 40;

  /// Step 10: 48 dp.
  static const double s10 = 48;

  /// Step 11: 64 dp.
  static const double s11 = 64;

  /// Horizontal screen gutter.
  static const double screenGutter = 16;

  /// Minimum touch target.
  static const double minTouchTarget = 48;
}

/// Shadows tinted with Surma ink. In dark theme prefer surface steps.
abstract final class BrandElevation {
  /// Elevation level 0.
  static const List<BoxShadow> e0 = <BoxShadow>[];

  /// Elevation level 1.
  static const List<BoxShadow> e1 = <BoxShadow>[
    BoxShadow(color: Color(0x141A1433), offset: Offset(0, 1), blurRadius: 2),
  ];

  /// Elevation level 2.
  static const List<BoxShadow> e2 = <BoxShadow>[
    BoxShadow(
      color: Color(0x1A1A1433),
      offset: Offset(0, 2),
      blurRadius: 6,
      spreadRadius: -1,
    ),
    BoxShadow(color: Color(0x0F1A1433), offset: Offset(0, 1), blurRadius: 2),
  ];

  /// Elevation level 3.
  static const List<BoxShadow> e3 = <BoxShadow>[
    BoxShadow(
      color: Color(0x291A1433),
      offset: Offset(0, 8),
      blurRadius: 20,
      spreadRadius: -4,
    ),
    BoxShadow(color: Color(0x0F1A1433), offset: Offset(0, 2), blurRadius: 4),
  ];

  /// Hard offset "sign-painter" shadow for the logo tile and badges.
  static const List<BoxShadow> stamp = <BoxShadow>[
    BoxShadow(color: Color(0xFF1A1433), offset: Offset(3, 3)),
  ];
}

/// Motion durations and curves.
abstract final class BrandMotion {
  /// instant: 80 ms.
  static const Duration instant = Duration(milliseconds: 80);

  /// fast: 140 ms.
  static const Duration fast = Duration(milliseconds: 140);

  /// base: 220 ms.
  static const Duration base = Duration(milliseconds: 220);

  /// slow: 320 ms.
  static const Duration slow = Duration(milliseconds: 320);

  /// stamp: 180 ms.
  static const Duration stamp = Duration(milliseconds: 180);

  /// splash: 700 ms.
  static const Duration splash = Duration(milliseconds: 700);

  /// standard easing.
  static const Curve standardCurve = Cubic(0.2, 0, 0, 1);

  /// enter easing.
  static const Curve enterCurve = Cubic(0, 0, 0, 1);

  /// exit easing.
  static const Curve exitCurve = Cubic(0.3, 0, 1, 1);

  /// Nuqta "stamp" with a small overshoot. Once per screen at most.
  static const Curve stampCurve = Cubic(0.34, 1.4, 0.64, 1);
}

/// Convenience ThemeData builders. They only wire tokens.
abstract final class BrandTheme {
  /// Light theme. Pass `urdu: true` for the Urdu locale.
  static ThemeData light({bool urdu = false}) {
    final base = urdu
        ? BrandTypography.urduTextTheme
        : BrandTypography.textTheme;
    return ThemeData(
      colorScheme: BrandColorSchemes.light,
      scaffoldBackgroundColor: BrandLight.background,
      fontFamily: urdu ? BrandFonts.urdu : BrandFonts.ui,
      textTheme: base.apply(
        bodyColor: BrandLight.textPrimary,
        displayColor: BrandLight.textPrimary,
      ),
      dividerColor: BrandLight.outline,
    );
  }

  /// Dark theme. Pass `urdu: true` for the Urdu locale.
  static ThemeData dark({bool urdu = false}) {
    final base = urdu
        ? BrandTypography.urduTextTheme
        : BrandTypography.textTheme;
    return ThemeData(
      colorScheme: BrandColorSchemes.dark,
      scaffoldBackgroundColor: BrandDark.background,
      fontFamily: urdu ? BrandFonts.urdu : BrandFonts.ui,
      textTheme: base.apply(
        bodyColor: BrandDark.textPrimary,
        displayColor: BrandDark.textPrimary,
      ),
      dividerColor: BrandDark.outline,
    );
  }
}

